                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        if dr==dc==0: continue
                        nr,nc=sr+dr,sc+dc
                        if (nr,nc) not in tc: continue
                        ob={p for p in tc if p!=(nr,nc)}
                        if abs(dr)+abs(dc)==1:
                            img={(r, sc+nc-c) for r,c in tc} if dc!=0 else {(sr+nr-r, c) for r,c in tc}
                        else:
                            img={(sr+nr-r, sc+nc-c) for r,c in tc}
                        if img&ob: continue
                        bad=any(not(0<=a<h and 0<=b<w) or (gi[a][b]!=bgc and (a,b)!=(sr,sc)) for a,b in img)
                        if bad: continue
                        stamps.append((img,col,sr,sc))
    out=[row[:] for row in gi]
    for img,col,sr,sc in sorted(stamps,key=lambda s:(s[2],s[3])):
