from collections import Counter,deque,defaultdict
def comps_of(g,bgc):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; ci=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bgc and not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; cc={(r,c)}
                while q:
                    a,b=q.popleft()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            na,nb=a+dr,b+dc
                            if 0<=na<h and 0<=nb<w and g[na][nb]==col and not seen[na][nb]:
                                seen[na][nb]=True; q.append((na,nb)); cc.add((na,nb))
                ci.append(cc)
    return ci
